type Role = "authority" | "organization" | "volunteer" | "responder";
type View = "command" | "map" | "zones" | "volunteers" | "citizens" | "risk" | "simulation" | "incidents" | "resources" | "responders" | "analytics" | "recovery" | "route" | "organization" | "my-zone" | "tasks" | "my-emergency" | "report";
type IncidentStatus = "Waiting for Responder" | "Assigned" | "Accepted" | "On the Way" | "Reached" | "Completed";
type ResourceStatus = "AVAILABLE" | "ASSIGNED" | "DEPLOYED" | "OFFLINE";
type DisasterType = "Flood" | "Cyclone" | "Fire" | "Earthquake";
type DisasterSeverity = "Low" | "Medium" | "High" | "Critical";
type RecoveryStatus = "Pending" | "Assigned" | "In Progress" | "Completed";
type RecoveryPriority = "CRITICAL" | "HIGH" | "MEDIUM";
type HazardType = "Open Drainage" | "Open Tank" | "Unprotected Water Body" | "Flood-Prone Area" | "Unsafe Structure" | "Blocked Drainage" | "Other Hazardous Location";
type MapLayer = "riskZones" | "incidents" | "volunteers" | "responders" | "shelters" | "organizations" | "hazards" | "recovery";

type Zone = { name: string; population: number; risk: number; level: "CRITICAL" | "HIGH" | "MEDIUM" | "LOW"; vulnerable: number; volunteer: string; surveyed: number; status: string; coordinates: [number, number] };
type CitizenForm = { householdId: string; zone: string; location: string; people: string; children: string; elderly: string; special: string; medical: string; mobility: string; contact: string; evacuation: boolean };
type CitizenRecord = CitizenForm & { collectedBy: string; createdAt: string; vulnerable: number };
type OrganizationRecord = { name: string; location: string; population: number; buildings: number; exits: number; shelters: number; shelterCapacity: number; resources: string; infrastructure: string; risk: number; preparedness: number };
type RecoveryCase = { id: string; asset: string; zone: string; priority: RecoveryPriority; status: RecoveryStatus; people: number; explanation: string; assignedTo: string; position: [number, number] };
type Hazard = { id: string; type: HazardType; zone: string; risk: "HIGH" | "CRITICAL" | "MEDIUM"; description: string; action: string; position: [number, number] };

