const markerKinds: Record<string, { label: string; tone: string }> = {
  critical: { label: "Critical incident", tone: "critical" }, high: { label: "High-risk zone", tone: "high" }, safe: { label: "Verified facility", tone: "safe" }, responder: { label: "Responder", tone: "responder" }, volunteer: { label: "Volunteer", tone: "volunteer" }, recoveryCritical: { label: "Recovery critical", tone: "critical" }, recoveryHigh: { label: "Recovery required", tone: "high" }, recoveryProgress: { label: "Recovery in progress", tone: "progress" }, recoverySafe: { label: "Restored", tone: "safe" }, hazard: { label: "Community hazard", tone: "critical" },
};

function loadStored<T>(key: string, fallback: T): T {
  if (typeof window === "undefined") return fallback;
  try { const stored = window.localStorage.getItem(key); return stored ? JSON.parse(stored) as T : fallback; } catch { return fallback; }
}

function markerIcon(kind: string) {
  const meta = markerKinds[kind] ?? markerKinds.safe;
  return L.divIcon({ className: "map-marker-shell", html: `<span class="map-marker map-marker-${meta.tone}"><i></i></span>`, iconSize: [26, 26], iconAnchor: [13, 13], popupAnchor: [0, -12] });
}

function MapRecenter({ active }: { active: boolean }) {
  const map = useMap();
  if (active) map.setView([19.066, 72.891], 13, { animate: true });
  return null;
}

function InteractiveMap({ simulationActive, incidentStatus, hazards, recoveryCases }: { simulationActive: boolean; incidentStatus: IncidentStatus; hazards: Hazard[]; recoveryCases: RecoveryCase[] }) {
  const [layers, setLayers] = useState<Record<MapLayer, boolean>>({ riskZones: true, incidents: true, volunteers: true, responders: true, shelters: true, organizations: true, hazards: true, recovery: true });
  const [hazardFilters, setHazardFilters] = useState<Record<HazardType, boolean>>(() => Object.fromEntries(["Open Drainage", "Open Tank", "Unprotected Water Body", "Flood-Prone Area", "Unsafe Structure", "Blocked Drainage", "Other Hazardous Location"].map((type) => [type, true])) as Record<HazardType, boolean>);
  const [showLayers, setShowLayers] = useState(false);
  const points = [
    { position: [19.066, 72.891] as [number, number], kind: "critical", layer: "incidents" as MapLayer, title: "INC-1042 · People trapped", detail: `5 people · 2 children · 1 elderly · ${incidentStatus}`, zone: "Zone B" },
    { position: [19.044, 72.871] as [number, number], kind: "high", layer: "incidents" as MapLayer, title: "Zone E · Medical assistance", detail: "12 affected · 5 vulnerable", zone: "Zone E" },
    { position: [19.102, 72.862] as [number, number], kind: "volunteer", layer: "volunteers" as MapLayer, title: "V-104 · Survey team", detail: "Assigned · 612 households surveyed", zone: "Zone A" },
    { position: [19.082, 72.912] as [number, number], kind: "safe", layer: "shelters" as MapLayer, title: "Shelter S-02 · Sports complex", detail: "Capacity 860 · 62% available", zone: "Zone C" },
    { position: [19.121, 72.886] as [number, number], kind: "responder", layer: "responders" as MapLayer, title: "R-04 · Rescue Team", detail: "Assigned · North command post", zone: "Zone D" },
    { position: [19.035, 72.904] as [number, number], kind: "safe", layer: "organizations" as MapLayer, title: "ABC University Clinic", detail: "Medical capacity 120 · Verified", zone: "Zone B" },
  ];
  const layerLabels: Array<[MapLayer, string]> = [["riskZones", "Risk Zones"], ["incidents", "Incidents"], ["volunteers", "Volunteers"], ["responders", "Responders"], ["shelters", "Shelters"], ["organizations", "Organizations"], ["hazards", "Community Hazards"], ["recovery", "Recovery Assets"]];
  const hazardTypes: HazardType[] = ["Open Drainage", "Open Tank", "Flood-Prone Area", "Unsafe Structure", "Blocked Drainage", "Unprotected Water Body", "Other Hazardous Location"];
  return <div className="map-shell">
    <MapContainer center={[19.082, 72.887]} zoom={12.8} scrollWheelZoom={true} zoomControl={false} className="leaflet-map">
      <TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
      {points.filter((point) => layers[point.layer]).map((point) => <Marker key={point.title} position={point.position} icon={markerIcon(point.kind)}><Popup><div className="map-popup"><span className={`eyebrow tone-${markerKinds[point.kind].tone}`}>{markerKinds[point.kind].label}</span><strong>{point.title}</strong><span>{point.detail}</span><small>{point.zone} · Simulated location</small></div></Popup></Marker>)}
      {layers.hazards && hazards.filter((hazard) => hazardFilters[hazard.type]).map((hazard) => <Marker key={hazard.id} position={hazard.position} icon={markerIcon("hazard")}><Popup><div className="map-popup"><span className="eyebrow tone-critical">COMMUNITY HAZARD · SIMULATED</span><strong>{hazard.type}</strong><span>{hazard.description}</span><small>{hazard.zone} · Risk {hazard.risk}</small><b>Recommended action: {hazard.action}</b></div></Popup></Marker>)}
      {layers.recovery && recoveryCases.map((item) => <Marker key={item.id} position={item.position} icon={markerIcon(item.status === "Completed" ? "recoverySafe" : item.status === "In Progress" ? "recoveryProgress" : item.priority === "CRITICAL" ? "recoveryCritical" : "recoveryHigh")}><Popup><div className="map-popup"><span className="eyebrow">RECOVERY ASSET · {item.status.toUpperCase()}</span><strong>{item.id} · {item.asset}</strong><span>{item.explanation}</span><small>{item.zone} · {item.people.toLocaleString()} people affected</small></div></Popup></Marker>)}
      {layers.riskZones && simulationActive && <LeafletCircle center={[19.066, 72.891]} radius={1250} pathOptions={{ color: "#d84a3a", fillColor: "#d84a3a", fillOpacity: 0.12, weight: 2, dashArray: "8 8" }} />}
      {simulationActive && <MapRecenter active={simulationActive} />}
    </MapContainer>
    <div className="map-control"><button className="map-control-toggle" onClick={() => setShowLayers((current) => !current)}><Layers size={14} /> Map layers <ChevronDown size={13} className={showLayers ? "rotate-180" : ""} /></button>{showLayers && <div className="map-layer-panel"><span className="eyebrow">VISIBLE LAYERS</span>{layerLabels.map(([key, label]) => <label key={key}><input type="checkbox" checked={layers[key]} onChange={() => setLayers((current) => ({ ...current, [key]: !current[key] }))} />{label}</label>)}<span className="eyebrow hazard-layer-heading">HAZARD CATEGORIES</span>{hazardTypes.map((type) => <label key={type}><input type="checkbox" checked={hazardFilters[type]} onChange={() => setHazardFilters((current) => ({ ...current, [type]: !current[type] }))} />{type}</label>)}</div>}</div>
    <div className="map-legend"><span><i className="legend-dot critical" />Critical</span><span><i className="legend-dot high" />Recovery required</span><span><i className="legend-dot medium" />In progress</span><span><i className="legend-dot safe" />Restored</span></div>
    <div className="map-note"><MapIcon size={12} /> Simulated Mumbai region · {layers.hazards ? "community hazards visible" : "hazards hidden"}</div>
  </div>;
}

function Icon({ icon: IconComponent, size = 16 }: { icon: ComponentType<{ size?: number; strokeWidth?: number }>; size?: number }) { return <IconComponent size={size} strokeWidth={1.8} />; }

function StatusBadge({ value }: { value: string }) {
  const normalized = value.toLowerCase();
  const tone = normalized.includes("critical") ? "critical" : normalized.includes("high") || normalized.includes("waiting") ? "high" : normalized.includes("completed") || normalized.includes("available") || normalized.includes("prepared") || normalized.includes("resolved") ? "safe" : normalized.includes("assigned") || normalized.includes("accepted") || normalized.includes("on the way") || normalized.includes("monitoring") ? "info" : "muted";
  return <span className={`status-badge status-${tone}`}><i />{value}</span>;
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="section-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{description && <p>{description}</p>}</div>{action}</div>;
}

function Panel({ title, eyebrow, children, className = "", action }: { title?: string; eyebrow?: string; children: ReactNode; className?: string; action?: ReactNode }) {
  return <section className={`panel ${className}`}><div className="panel-head">{title && <div><span className="eyebrow">{eyebrow ?? "EVIDENCE"}</span><h2>{title}</h2></div>}{action}</div>{children}</section>;
}

function KpiCard({ label, value, detail, icon: IconComponent, tone = "teal", trend }: { label: string; value: string; detail: string; icon: ComponentType<{ size?: number; strokeWidth?: number }>; tone?: string; trend?: string }) {
  return <div className={`kpi-card kpi-${tone}`}><div className="kpi-top"><span>{label}</span><span className="kpi-icon"><Icon icon={IconComponent} size={15} /></span></div><strong>{value}</strong><div className="kpi-bottom"><small>{detail}</small>{trend && <b>{trend}</b>}</div></div>;
}

function ProgressBar({ value, tone = "teal" }: { value: number; tone?: string }) { return <div className="progress-track"><span className={`progress-fill fill-${tone}`} style={{ width: `${Math.min(100, value)}%` }} /></div>; }

